def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and r > 0:
            total += x * r ** 3
            weight += x
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None:
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [0.0] * n
    neighbors = s.get('neighbors', [])
    for p in neighbors:
        i = p['i']
        d = p.get('distance_A')
        if d is not None and d > 0 and occ[p['j']] > 0:
            if nearest[i] == 0 or d < nearest[i]:
                nearest[i] = d
    coordination = [0.0] * n
    for p in neighbors:
        i = p['i']
        d = p.get('distance_A')
        if d is not None and d > 0 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[p['j']]
    weight = sum(occ)
    return float(sum(occ[i] * coordination[i] for i in range(n)) / weight) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [0.0] * n
    neighbors = s.get('neighbors', [])
    for p in neighbors:
        i = p['i']
        d = p.get('distance_A')
        if d is not None and d > 0 and occ[p['j']] > 0:
            if nearest[i] == 0 or d < nearest[i]:
                nearest[i] = d
    coordination = [0.0] * n
    for p in neighbors:
        i = p['i']
        d = p.get('distance_A')
        if d is not None and d > 0 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[p['j']]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * coordination[i] for i in range(n)) / weight
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n)) / weight
    return float(math.sqrt(max(0.0, variance)) / mean)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    elements = [t.get('element') for t in sites]
    total_occ = sum(occ)
    if total_occ <= 0:
        return 0.0
    amounts = {}
    for i in range(n):
        e = elements[i]
        amounts[e] = amounts.get(e, 0.0) + occ[i]
    expected = 1.0 - sum((x / total_occ) ** 2 for x in amounts.values())
    neighbors = s.get('neighbors', [])
    nearest = [0.0] * n
    for p in neighbors:
        i = p['i']
        d = p.get('distance_A')
        if d is not None and d > 0 and occ[p['j']] > 0:
            if nearest[i] == 0 or d < nearest[i]:
                nearest[i] = d
    unlike = 0.0
    weight = 0.0
    for p in neighbors:
        i = p['i']
        j = p['j']
        d = p.get('distance_A')
        if d is not None and d > 0 and d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if elements[i] != elements[j]:
                unlike += w
    return float(unlike / weight - expected) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    matrix = s.get('lattice', {}).get('matrix')
    n = len(sites)
    if n == 0 or matrix is None:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    neighbors = s.get('neighbors', [])
    nearest = [0.0] * n
    for p in neighbors:
        i = p['i']
        d = p.get('distance_A')
        if d is not None and d > 0 and occ[p['j']] > 0:
            if nearest[i] == 0 or d < nearest[i]:
                nearest[i] = d
    vectors = [[0.0, 0.0, 0.0] for t in sites]
    count = [0.0] * n
    for p in neighbors:
        i = p['i']
        j = p['j']
        d = p.get('distance_A')
        if d is not None and d > 0 and d <= 1.25 * nearest[i] and occ[j] > 0:
            delta = [sites[j]['frac_coords'][k] + p['image'][k] - sites[i]['frac_coords'][k] for k in range(3)]
            cart = [sum(delta[k] * matrix[k][a] for k in range(3)) for a in range(3)]
            length = math.sqrt(sum(x * x for x in cart))
            if length > 0:
                count[i] += occ[j]
                for a in range(3):
                    vectors[i][a] += occ[j] * cart[a] / length
    total = 0.0
    weight = 0.0
    for i in range(n):
        if count[i] > 0:
            total += occ[i] * sum(x * x for x in vectors[i]) / (count[i] * count[i])
            weight += occ[i]
    return float(total / weight) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    inner = [0.0] * n
    outer = [0.0] * n
    for p in s.get('neighbors', []):
        i = p['i']
        d = p.get('distance_A')
        if d is not None and d > 0:
            w = occ[p['j']]
            if d <= 5.0:
                outer[i] += w
            if d <= 2.5:
                inner[i] += w
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    total = sum(occ[i] * math.log((outer[i] + occ[i]) / (inner[i] + occ[i])) / math.log(2.0) for i in range(n) if occ[i] > 0)
    return float(total / weight)

def feature(s):
    sites = s.get('sites', [])
    props = s.get('element_properties', {})
    en = [props.get(t.get('element'), {}).get('eneg') for t in sites]
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    total = 0.0
    for p in s.get('neighbors', []):
        i = p['i']
        j = p['j']
        d = p.get('distance_A')
        if d is not None and d > 0 and d < 4.5 and en[i] is not None and en[j] is not None:
            total += occ[i] * occ[j] * (en[i] - en[j]) ** 2 * (1.0 - d / 4.5) ** 2 / d
    return float(0.5 * total / weight)

def feature(s):
    sites = s.get('sites', [])
    props = s.get('element_properties', {})
    radii = [props.get(t.get('element'), {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    total = 0.0
    for p in s.get('neighbors', []):
        i = p['i']
        j = p['j']
        d = p.get('distance_A')
        if d is not None and d > 0 and radii[i] is not None and radii[j] is not None:
            r = radii[i] + radii[j]
            if r > d:
                total += occ[i] * occ[j] * (r / d - 1.0) ** 2
    return float(0.5 * total / weight)
